<?php

namespace Database\Seeders;

use App\Cms\SectionRegistry;
use App\Models\Menu;
use App\Models\MenuItem;
use App\Models\Page;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

/**
 * Imports the template's real content (generated by tools/cms/build_pages.py) so the admin panel is
 * pre-populated. Existing pages are never overwritten, so editors' changes survive re-seeding.
 */
class ContentSeeder extends Seeder
{
    public function run(): void
    {
        $file = database_path('content/pages.json');
        $pages = json_decode(file_get_contents($file), true);

        DB::transaction(function () use ($pages) {
            foreach (array_values($pages) as $i => $def) {
                if (Page::where('slug', $def['slug'])->exists()) {
                    continue;
                }
                $page = Page::create([
                    'title' => $def['title'], 'slug' => $def['slug'], 'template' => $def['template'],
                    'status' => $def['slug'] === '_global' ? 'draft' : 'published',
                    'is_home' => $def['is_home'] ?? false, 'is_system' => $def['is_system'] ?? false, 'position' => $i,
                ]);
                foreach ($def['sections'] as $pos => [$type, $label]) {
                    $d = SectionRegistry::defaults($type);
                    $page->sections()->create([
                        'type' => $type, 'label' => $label, 'position' => $pos, 'is_visible' => true,
                        'content' => ['slots' => $d['slots'], 'groups' => $d['groups']],
                    ]);
                }
                if (! empty($def['seo_title']) || ! empty($def['meta_description'])) {
                    $page->seo()->create(['title' => $def['seo_title'] ?? null, 'description' => $def['meta_description'] ?? null]);
                }
            }

            $menu = Menu::firstOrCreate(['location' => 'primary'], ['name' => 'Primary navigation']);
            if ($menu->items()->count() === 0) {
                $home = Page::where('is_home', true)->first();
                MenuItem::create(['menu_id' => $menu->id, 'label' => 'Home', 'type' => 'page', 'page_id' => $home?->id, 'position' => 0]);
            }
        });
    }
}
